  const bin = mkdtempSync(join(tmpdir(), 'detran-apply-revision-stubs-'));
  makeStub(bin, 'psql', 'printf "%s\\n" psql-called');
  const result = run(
    'bash',
    [join(root, 'backend/database/apply.sh'), '--full'],
    {
      DB_NAME: authorizedDatabase,
      [fullAuthorization]: '1',
      PATH: `${bin}:${process.env.PATH}`,
    },
  );
  rmSync(bin, { recursive: true, force: true });
  assert.equal(result.status, 0, `${result.stdout}${result.stderr}`);
